parameters.style:
html, body { background-color: var(--background); }

/* Dark: the system asks for it and the person has not chosen light. */
@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
    color-scheme: dark;
    --background: #161718;
    --foreground: #e7e7e4;
    --surface: #1f2022;
    --surface-raised: #25272a;
    --muted: #2b2d30;
    --muted-foreground: #a4a8ac;
    --primary: #8aa9f2;
    --primary-hover: #a6bef6;
    --primary-foreground: #10141f;
    --ring: #8aa9f2;
    --destructive: #f0877e;
    --destructive-hover: #f4a49d;
    --destructive-foreground: #1b100f;
    --secondary: #2b2d30;
    --secondary-hover: #34373a;
    --secondary-foreground: #e7e7e4;
    --accent: #1e2941;
    --accent-foreground: #b8cbf8;
    --border: #323437;
    --border-subtle: #2a2c2f;
    --border-strong: #474a4e;
    --border-control: #83878c;
  }
  :root:not([data-theme="light"]) .todo-theme-to-dark { display: none !important; }
}

/* Dark: the person chose it on a light system. */
:root[data-theme="dark"] {
  color-scheme: dark;
  --background: #161718;
  --foreground: #e7e7e4;
  --surface: #1f2022;
  --surface-raised: #25272a;
  --muted: #2b2d30;
  --muted-foreground: #a4a8ac;
  --primary: #8aa9f2;
  --primary-hover: #a6bef6;
  --primary-foreground: #10141f;
  --ring: #8aa9f2;
  --destructive: #f0877e;
  --destructive-hover: #f4a49d;
  --destructive-foreground: #1b100f;
  --secondary: #2b2d30;
  --secondary-hover: #34373a;
  --secondary-foreground: #e7e7e4;
  --accent: #1e2941;
  --accent-foreground: #b8cbf8;
  --border: #323437;
  --border-subtle: #2a2c2f;
  --border-strong: #474a4e;
  --border-control: #83878c;
}
:root[data-theme="dark"] .todo-theme-to-dark { display: none !important; }

/* Light shows the moon; dark shows the sun. */
@media not all and (prefers-color-scheme: dark) {
  :root:not([data-theme="dark"]) .todo-theme-to-light { display: none !important; }
}
:root[data-theme="light"] .todo-theme-to-light { display: none !important; }

/* Reminders: no bell unless the host can send them; then the one that changes the state. */
:root:not([data-reminders]) .todo-reminders-turn-on { display: none !important; }
:root:not([data-reminders="on"]) .todo-reminders-turn-off { display: none !important; }
:root[data-reminders="on"] .todo-reminders-turn-on { display: none !important; }

parameters.functionScript:
var KEY = "nodegx-todo-list-theme";
function systemTheme() {
  return window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
}
function chosenTheme() {
  var v = null;
  try { v = window.localStorage.getItem(KEY); } catch (e) { v = window.__todoTheme || null; }
  return v === 'dark' || v === 'light' ? v : null;
}
function remember(v) {
  window.__todoTheme = v;
  try { if (v) window.localStorage.setItem(KEY, v); else window.localStorage.removeItem(KEY); } catch (e) {}
}
function applyTheme(v) {
  if (v) document.documentElement.setAttribute('data-theme', v);
  else document.documentElement.removeAttribute('data-theme');
}
applyTheme(chosenTheme());
